"""Fraction comparison used by the current practice page."""
from fractions import Fraction

def compare(left, right):
    a, b = Fraction(*left), Fraction(*right)
    return 'greater' if a > b else 'less' if a < b else 'equal'

def explanation(left, right):
    if left[1] == right[1]:
        larger = 'A' if left[0] > right[0] else 'B'
        return f'{larger} has more equal-sized parts.'
    return f'The comparison is {compare(left, right)}.'

def render(problem):
    return {'verdict': compare(*problem), 'explanation': explanation(*problem)}

"""A small retrieval candidate; no server execution is necessary for inspection."""
def retrieve(query, documents):
    return [{'text': d['text'], 'source': {'document_id': d['id'], 'page': d['page']}, 'score': 0.8}
            for d in documents if query.lower() in d['text'].lower()]

export function renderAnswer(answer) {
  const citations = answer.citations.map(c => `<a href="${c.url}">${c.label}</a>`).join('');
  return `<article>${answer.answer}${citations}</article>`;
}
